package com.companages.controller; import com.companages.dto.MemberDtos.ChartNode; import com.companages.service.OrganizationChartService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/organizations/{organizationId}/organization-chart") public class OrganizationChartController { private final OrganizationChartService service; public OrganizationChartController(OrganizationChartService s){service=s;} @GetMapping List<ChartNode> get(@PathVariable Long organizationId,@RequestParam(required=false)String search){return service.chart(organizationId,search);} }
